package com.campusconnect.chat;
import com.campusconnect.rag.RagService; import com.campusconnect.user.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.security.Principal; import java.util.*;
@Service public class ChatService {private final String baseUrl,apiKey,model;private final RestClient client=RestClient.builder().build();private final RagService rag;private final UserRepository users;private final ChatTurnRepository turns;
public ChatService(@Value("${app.ai.base-url}") String b,@Value("${app.ai.api-key}") String k,@Value("${app.ai.model}") String m,RagService r,UserRepository u,ChatTurnRepository t){baseUrl=b;apiKey=k;model=m;rag=r;users=u;turns=t;}
@SuppressWarnings({"unchecked","rawtypes"}) public ChatDtos.ChatResponse answer(String message,Principal principal){var sources=rag.retrieve(message,4);String context=sources.stream().map(s->"["+s.get("title")+" | chunk "+s.get("chunkIndex")+"]\n"+s.get("content")).reduce((a,b)->a+"\n\n---\n\n"+b).orElse("No matching campus documents were found.");String answer;boolean configured=baseUrl!=null&&!baseUrl.isBlank()&&apiKey!=null&&!apiKey.isBlank()&&model!=null&&!model.isBlank();if(!configured){answer="AI is not configured. Add AI_BASE_URL, AI_API_KEY, and AI_MODEL. Retrieved campus context: "+(sources.isEmpty()?"No matching documents found.":context.substring(0,Math.min(context.length(),3500)));}else{String system="You are CampusConnect AI. Answer accurately and distinguish retrieved campus material from general knowledge. If context does not answer the question, say so rather than inventing campus policy. Cite document titles in brackets when using context. Retrieved campus context follows:\n"+context;Map payload=Map.of("model",model,"messages",List.of(Map.of("role","system","content",system),Map.of("role","user","content",message)),"temperature",0.2);Map response=client.post().uri(baseUrl.replaceAll("/+$","")+"/chat/completions").contentType(MediaType.APPLICATION_JSON).headers(h->h.setBearerAuth(apiKey)).body(payload).retrieve().body(Map.class);try{List choices=(List)response.get("choices");Map first=(Map)choices.get(0);Map content=(Map)first.get("message");answer=String.valueOf(content.get("content"));}catch(Exception ex){throw new IllegalStateException("AI provider returned an unexpected response.");}}
var user=users.findByEmailIgnoreCase(principal.getName()).orElseThrow();turns.save(new ChatTurn(user,message,answer));return new ChatDtos.ChatResponse(answer,configured,sources);}
public List<Map<String,Object>> history(Principal p){return turns.findTop100ByUserEmailOrderByCreatedAtDesc(p.getName()).stream().map(t->Map.<String,Object>of("id",t.getId(),"question",t.getQuestion(),"answer",t.getAnswer(),"createdAt",t.getCreatedAt())).toList();}}
